CREATE TABLE public.misa_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200), details text NOT NULL DEFAULT '', created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.misa_projects TO authenticated;
GRANT ALL ON public.misa_projects TO service_role;
ALTER TABLE public.misa_projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Team manages Misa projects" ON public.misa_projects FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE TABLE public.misa_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES public.misa_projects(id) ON DELETE CASCADE, title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 300), details text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','in_process','ready')), created_by uuid NOT NULL DEFAULT auth.uid(), updated_by uuid DEFAULT auth.uid(), updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.misa_tasks TO authenticated;
GRANT ALL ON public.misa_tasks TO service_role;
ALTER TABLE public.misa_tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Team manages Misa tasks" ON public.misa_tasks FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE TABLE public.misa_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES public.misa_projects(id) ON DELETE CASCADE, filename text NOT NULL, storage_path text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.misa_sources TO authenticated;
GRANT ALL ON public.misa_sources TO service_role;
ALTER TABLE public.misa_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Team manages Misa sources" ON public.misa_sources FOR ALL TO authenticated USING (true) WITH CHECK (true);
CREATE POLICY "Team reads Misa files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='misa-files');
CREATE POLICY "Team uploads Misa files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='misa-files');
CREATE POLICY "Team removes Misa files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id='misa-files');
CREATE FUNCTION public.misa_task_stamp() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); NEW.updated_by=auth.uid(); RETURN NEW; END $$;
CREATE TRIGGER misa_task_updated BEFORE UPDATE ON public.misa_tasks FOR EACH ROW EXECUTE FUNCTION public.misa_task_stamp();